export const FUEL_STEP_ML = 100;

/**
 * Надбавка за прицеп в мл на километр.
 *
 * Записана у диспетчерской как 2 литра на 100 км — это плоская прибавка ВЕЛИЧИНАМИ К НОРМЕ
